const rows = Array.isArray(msg.payload) ? msg.payload : (msg.payload?.rows || []);
const now = new Date().toISOString();

if (!rows.length) {
  msg.ui = {
    empty: true,
    title: "Duplicados exactos",
    subtitle: "✅ No hay duplicados exactos para revisar (todo ok)",
    keepId: null,
    rows: [],
    generatedAt: now
  };
  msg.payload = msg.ui;
  return msg;
}

// vienen ordenados por id ASC (tu query ya lo hace igual)
const sorted = rows.slice().sort((a,b)=> (a.idTiposDeMovimiento||0) - (b.idTiposDeMovimiento||0));
const keepId = sorted[0].idTiposDeMovimiento;

msg.ui = {
  empty: false,
  title: "Duplicados exactos",
  subtitle: `Grupo encontrado (${sorted.length} registros) · sugerencia: conservar ID ${keepId}`,
  keepId,
  rows: sorted,
  generatedAt: now
};

msg.payload = msg.ui;
return msg;

const p = msg.payload;

if (!p || p.action !== "mark_error") return null;

const id = Number(p.id);
if (!Number.isFinite(id)) return null;

msg.topic = `
UPDATE TiposDeMovimiento
SET TiposDeMovimiento = 'ERROR_REGISTRO'
WHERE idTiposDeMovimiento = ${id}
  AND TiposDeMovimiento NOT IN ('PABAJO','MIN_PROD_BOLSA')
  AND TiposDeMovimiento <> 'ERROR_REGISTRO'
LIMIT 1;
`;

msg.payload = null;
return msg;

// MySQL node suele devolver algo tipo:
// { fieldCount, affectedRows, insertId, ... }
// o a veces un array con eso.

const res = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;
const affected = res && (res.affectedRows ?? res.affected_rows ?? res['affectedRows']);

const originalId = (msg._markErrorId || (msg.payload && msg.payload.id) || msg.id);

if (affected === 1) {
  msg.payload = {
    topic: "OK",
    payload: `✅ Marcado como ERROR_REGISTRO (ID ${originalId})`,
    type: "success",
    timeout: 2500
  };
} else {
  msg.payload = {
    topic: "Sin cambios",
    payload: `⚠️ No se modificó nada (quizá ya era ERROR_REGISTRO o fue filtrado).`,
    type: "warning",
    timeout: 3500
  };
}

return msg;

// Deja pasar el toast tal cual por salida 1
// y además emite un "pulso" por salida 2 para refrescar (si affectedRows==1)

const toastMsg = RED.util.cloneMessage(msg);

const res = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;
const affected = res && (res.affectedRows ?? res.affected_rows ?? res['affectedRows']);

let refreshMsg = null;
if (Number(affected) === 1) {
    refreshMsg = {
        payload: Date.now(),
        topic: "auto_refresh_after_update",
        _refresh: true
    };
}

return [toastMsg, refreshMsg];
